    <script type="module">
        /* 更新进度条辅助函数 */
        function updateProgressBar(barId, valueId, rawValue, min = 0, max = 100, color = null) {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;

                $(`#${valueId}`).text(clampedValue);
                const cssProps = { width: `${percentage}%` };
                if (color) {
                    cssProps.backgroundImage = 'none';
                    cssProps.backgroundColor = color;
                }
                $(`#${barId}`).css(cssProps);
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>无法加载状态数据</div>");
                    return;
                }

                /* Keegan 好感度：范围 0 ~ 100 */
                updateProgressBar(
                    'keegan-affection-bar',
                    'keegan-affection',
                    _.get(characterData, 'Keegan.好感度', 0),
                    0, 100, '#c0392b'
                );

                /* Keegan 性欲值：范围 0 ~ 100 */
                updateProgressBar(
                    'keegan-desire-bar',
                    'keegan-desire',
                    _.get(characterData, 'Keegan.性欲值', 0),
                    0, 100, '#7a2318'
                );

                /* Keegan 政务牵挂度：范围 0 ~ 100 */
                updateProgressBar(
                    'keegan-preoccupation-bar',
                    'keegan-preoccupation',
                    _.get(characterData, 'Keegan.政务牵挂度', 0),
                    0, 100, '#1f9c73'
                );

                /* 文本类属性 */
                $('#keegan-outfit').text(_.get(characterData, 'Keegan.衣着', 'N/A'));
                $('#keegan-status-badge').text(_.get(characterData, 'Keegan.状态', 'N/A'));
                $('#keegan-inner-voice').text(_.get(characterData, 'Keegan.心声', 'N/A'));
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
